import type { ServerFontResourceDescriptor } from 'expo-font';
import { type ReactNode } from 'react';

import {
  type ExtraScriptTag,
  getHydrationFlagScriptContents,
  getLoaderDataScriptContents,
} from './html';

type CreateNodeResult = {
  headNodes?: ReactNode[];
  bodyNodes?: ReactNode[];
};

export function createInjectedCssAsNodes(hrefs: string[]): CreateNodeResult {
  return {
    headNodes: hrefs.flatMap((href) => [
      <link key={`css-preload-${href}`} rel="preload" href={href} as="style" />,
      <link key={`css-stylesheet-${href}`} rel="stylesheet" href={href} />,
    ]),
  };
}

export function createInjectedInlineCssAsNodes(
  inlineCss: { source: string; hmrId?: string }[] = []
): CreateNodeResult {
  return {
    headNodes: inlineCss.map(({ source, hmrId }, index) => (
      <style
        key={hmrId ? `inline-css-${hmrId}` : `inline-css-${index}`}
        data-expo-css-hmr={hmrId}
        dangerouslySetInnerHTML={{ __html: source }}
      />
    )),
  };
}

export function createInjectedScriptAsNodes(srcs: string[]): CreateNodeResult {
  return {
    headNodes: srcs.map((src) => (
      <link key={`script-preload-${src}`} rel="preload" href={src} as="script" />
    )),
    bodyNodes: srcs.map((src) => <script key={`script-src-${src}`} defer src={src} />),
  };
}

/**
 * Returns a `<link rel="icon">` head node for the given favicon URL. Companion to
 * `createInjectedFaviconAsString` in `utils/html.ts`.
 */
export function createInjectedFaviconAsNodes(href: string): CreateNodeResult {
  return {
    headNodes: [<link key={`favicon-${href}`} rel="icon" href={href} />],
  };
}

/**
 * Returns `<script>` head nodes for each {@link ExtraScriptTag}. Companion to
 * `createInjectedExtraScriptTagsAsString` in `utils/html.ts`.
 */
export function createInjectedExtraScriptTagsAsNodes(tags: ExtraScriptTag[]): CreateNodeResult {
  return {
    headNodes: tags.map((tag, index) =>
      tag.platform === 'web' ? (
        <script key={`extra-script-${index}`} src={tag.src} />
      ) : (
        <script
          key={`extra-script-${index}`}
          type="type/expo"
          src={tag.src}
          data-platform={tag.platform}
        />
      )
    ),
  };
}

export function getBootstrapContents({
  hydrate = true,
  loadedData,
}: {
  hydrate: boolean;
  loadedData: Record<string, unknown> | null;
}): string {
  const parts = [];

  if (hydrate) {
    parts.push(getHydrationFlagScriptContents());
  }

  if (loadedData) {
    parts.push(getLoaderDataScriptContents(loadedData));
  }

  return parts.join('\n');
}

export function createInjectedFontsAsNodes(
  descriptors: ServerFontResourceDescriptor[]
): ReactNode[] {
  return descriptors.map((descriptor) => {
    switch (descriptor.type) {
      case 'style':
        return (
          <style
            key={`font-style-${descriptor.id}`}
            id={descriptor.id}
            dangerouslySetInnerHTML={{ __html: descriptor.css }}
          />
        );
      case 'link':
        return (
          <link
            key={`font-link-${descriptor.href}`}
            rel={descriptor.rel}
            href={descriptor.href}
            as={descriptor.as}
            crossOrigin={descriptor.crossOrigin}
          />
        );
      default:
        return null;
    }
  });
}
